import { FastifyInstance } from 'fastify'
import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest'
import { system } from '../../../../src/app/helper/system/system'
import { AppSystemProp } from '../../../../src/app/helper/system/system-props'
import { MCP_OAUTH_REDIRECT_URI, mcpOAuthTestHelpers } from '../../../helpers/mcp-oauth'
import { setupTestEnvironment } from '../../../helpers/test-setup'

let app: FastifyInstance

const TLS_PROXY_HEADERS = {
    'x-forwarded-proto': 'https',
    'x-forwarded-host': 'mcp.customer.example.com',
}

async function discovery(headers: Record<string, string>): Promise<Record<string, string>> {
    const res = await app.inject({ method: 'GET', url: '/.well-known/oauth-authorization-server', headers })
    return res.json()
}

describe('MCP OAuth deployment shapes', () => {
    beforeAll(async () => {
        app = await setupTestEnvironment({ fresh: true })
    })

    afterAll(() => {
        vi.restoreAllMocks()
    })

    describe('behind a TLS-terminating proxy', () => {
        it('advertises https endpoints on the customer host, never the internal one', async () => {
            const metadata = await discovery(TLS_PROXY_HEADERS)

            for (const field of ['issuer', 'authorization_endpoint', 'token_endpoint', 'registration_endpoint', 'revocation_endpoint']) {
                expect(metadata[field], field).toMatch(/^https:\/\/mcp\.customer\.example\.com/)
            }
        })

        it('sends the consent redirect to the customer host so the browser can reach it', async () => {
            const client = await mcpOAuthTestHelpers.registerClient({ app, tokenEndpointAuthMethod: '<REDACTED>' })
            const { challenge } = mcpOAuthTestHelpers.generatePkce()

            const res = await app.inject({
                method: 'GET',
                headers: TLS_PROXY_HEADERS,
                url: `/authorize?client_id=${client.client_id}&redirect_uri=${encodeURIComponent(MCP_OAUTH_REDIRECT_URI)}&response_type=code&code_challenge=${challenge}&code_challenge_method=S256`,
            })

            expect(res.statusCode).toBe(302)
            expect(res.headers.location).toMatch(/^https:\/\/mcp\.customer\.example\.com\/mcp-authorize\?/)
        })

        it('points the protected resource metadata at the customer host', async () => {
            const res = await app.inject({
                method: 'GET',
                url: '/.well-known/oauth-protected-resource/mcp',
                headers: TLS_PROXY_HEADERS,
            })

            expect(res.json().resource).toBe('https://mcp.customer.example.com/mcp')
            expect(res.json().authorization_servers).toEqual(['https://mcp.customer.example.com'])
        })

        it('challenges an unauthenticated MCP call with a reachable metadata URL', async () => {
            const res = await app.inject({ method: 'POST', url: '/mcp', headers: TLS_PROXY_HEADERS })

            expect(res.statusCode).toBe(401)
            expect(res.headers['www-authenticate']).toContain('https://mcp.customer.example.com/.well-known/oauth-protected-resource/mcp')
        })
    })

    describe('hosted under a path prefix', () => {
        const PREFIXED_FRONTEND_URL = 'https://apps.customer.example.com/automation'

        beforeAll(() => {
            const realGet = system.get.bind(system)
            const realGetOrThrow = system.getOrThrow.bind(system)
            vi.spyOn(system, 'get').mockImplementation((prop) => prop === AppSystemProp.FRONTEND_URL ? PREFIXED_FRONTEND_URL : realGet(prop))
            vi.spyOn(system, 'getOrThrow').mockImplementation((prop) => prop === AppSystemProp.FRONTEND_URL ? PREFIXED_FRONTEND_URL : realGetOrThrow(prop))
        })

        it('advertises every endpoint under the configured prefix', async () => {
            const metadata = await discovery({ 'x-forwarded-proto': 'https', 'x-forwarded-host': 'apps.customer.example.com' })

            expect(metadata.issuer).toBe('https://apps.customer.example.com/automation')
            expect(metadata.token_endpoint).toBe('https://apps.customer.example.com/automation/token')
            expect(metadata.registration_endpoint).toBe('https://apps.customer.example.com/automation/register')
        })

        it('sends the consent redirect to the hostname root, the only path the app can route', async () => {
            const client = await mcpOAuthTestHelpers.registerClient({ app, tokenEndpointAuthMethod: '<REDACTED>' })
            const { challenge } = mcpOAuthTestHelpers.generatePkce()

            const res = await app.inject({
                method: 'GET',
                headers: { 'x-forwarded-proto': 'https', 'x-forwarded-host': 'apps.customer.example.com' },
                url: `/authorize?client_id=${client.client_id}&redirect_uri=${encodeURIComponent(MCP_OAUTH_REDIRECT_URI)}&response_type=code&code_challenge=${challenge}&code_challenge_method=S256`,
            })

            expect(res.statusCode).toBe(302)
            expect(res.headers.location).toMatch(/^https:\/\/apps\.customer\.example\.com\/mcp-authorize\?/)
        })
    })

    describe('with MCP served from its own hostname', () => {
        const DUAL_FRONTEND_URL = 'https://apps.customer.example.com/automation'
        const DUAL_MCP_URL = 'https://mcp.customer.example.com'
        const mcpHostHeaders = { 'x-forwarded-proto': 'https', 'x-forwarded-host': 'mcp.customer.example.com' }
        const frontendHostHeaders = { 'x-forwarded-proto': 'https', 'x-forwarded-host': 'apps.customer.example.com' }

        beforeAll(() => {
            const realGet = system.get.bind(system)
            const realGetOrThrow = system.getOrThrow.bind(system)
            vi.spyOn(system, 'get').mockImplementation((prop) => {
                if (prop === AppSystemProp.MCP_URL) {
                    return DUAL_MCP_URL
                }
                if (prop === AppSystemProp.FRONTEND_URL) {
                    return DUAL_FRONTEND_URL
                }
                return realGet(prop)
            })
            vi.spyOn(system, 'getOrThrow').mockImplementation((prop) => prop === AppSystemProp.FRONTEND_URL ? DUAL_FRONTEND_URL : realGetOrThrow(prop))
        })

        it('advertises the MCP host without the frontend path prefix', async () => {
            const metadata = await discovery(mcpHostHeaders)

            expect(metadata.issuer).toBe(DUAL_MCP_URL)
            expect(metadata.token_endpoint).toBe(`${DUAL_MCP_URL}/token`)
            expect(metadata.registration_endpoint).toBe(`${DUAL_MCP_URL}/register`)
        })

        it('keeps advertising the prefixed frontend base on the frontend host', async () => {
            const metadata = await discovery(frontendHostHeaders)

            expect(metadata.issuer).toBe(DUAL_FRONTEND_URL)
            expect(metadata.token_endpoint).toBe(`${DUAL_FRONTEND_URL}/token`)
        })

        it('points protected resource metadata at the MCP host', async () => {
            const res = await app.inject({
                method: 'GET',
                url: '/.well-known/oauth-protected-resource/mcp',
                headers: mcpHostHeaders,
            })

            expect(res.json().resource).toBe(`${DUAL_MCP_URL}/mcp`)
            expect(res.json().authorization_servers).toEqual([DUAL_MCP_URL])
        })

        it('challenges an unauthenticated MCP call on the MCP host with its own metadata URL', async () => {
            const res = await app.inject({ method: 'POST', url: '/mcp', headers: mcpHostHeaders })

            expect(res.statusCode).toBe(401)
            expect(res.headers['www-authenticate']).toContain(`${DUAL_MCP_URL}/.well-known/oauth-protected-resource/mcp`)
        })

        it('sends consent to the frontend origin, so the user signs in on the main host', async () => {
            const client = await mcpOAuthTestHelpers.registerClient({ app, tokenEndpointAuthMethod: '<REDACTED>' })
            const { challenge } = mcpOAuthTestHelpers.generatePkce()

            const res = await app.inject({
                method: 'GET',
                headers: mcpHostHeaders,
                url: `/authorize?client_id=${client.client_id}&redirect_uri=${encodeURIComponent(MCP_OAUTH_REDIRECT_URI)}&response_type=code&code_challenge=${challenge}&code_challenge_method=S256`,
            })

            expect(res.statusCode).toBe(302)
            expect(res.headers.location).toMatch(/^https:\/\/apps\.customer\.example\.com\/mcp-authorize\?/)
        })

        it('names each host as the OpenID issuer, so workload tokens still match on the frontend host', async () => {
            const onMcpHost = await app.inject({ method: 'GET', url: '/.well-known/openid-configuration', headers: mcpHostHeaders })
            const onFrontendHost = await app.inject({ method: 'GET', url: '/.well-known/openid-configuration', headers: frontendHostHeaders })

            expect(onMcpHost.json().issuer).toBe(DUAL_MCP_URL)
            expect(onFrontendHost.json().issuer).toBe(DUAL_FRONTEND_URL)
        })

        it('recognises the MCP host from an unchanged Host header when the proxy sends no X-Forwarded-Host', async () => {
            const metadata = await discovery({ 'host': 'mcp.customer.example.com', 'x-forwarded-proto': 'https' })

            expect(metadata.issuer).toBe(DUAL_MCP_URL)
        })

        it('leaves consent on the request host for a host matching neither setting', async () => {
            const client = await mcpOAuthTestHelpers.registerClient({ app, tokenEndpointAuthMethod: '<REDACTED>' })
            const { challenge } = mcpOAuthTestHelpers.generatePkce()

            const res = await app.inject({
                method: 'GET',
                headers: { 'x-forwarded-proto': 'https', 'x-forwarded-host': 'byo.customer.example.com' },
                url: `/authorize?client_id=${client.client_id}&redirect_uri=${encodeURIComponent(MCP_OAUTH_REDIRECT_URI)}&response_type=code&code_challenge=${challenge}&code_challenge_method=S256`,
            })

            expect(res.statusCode).toBe(302)
            expect(res.headers.location).toMatch(/^https:\/\/byo\.customer\.example\.com\/mcp-authorize\?/)
        })
    })

    describe('with an http AP_FRONTEND_URL behind a TLS-terminating proxy', () => {
        const HTTP_FRONTEND_URL = 'http://apps.customer.example.com'

        beforeAll(() => {
            vi.restoreAllMocks()
            const realGet = system.get.bind(system)
            const realGetOrThrow = system.getOrThrow.bind(system)
            vi.spyOn(system, 'get').mockImplementation((prop) => {
                if (prop === AppSystemProp.MCP_URL) {
                    return undefined
                }
                if (prop === AppSystemProp.FRONTEND_URL) {
                    return HTTP_FRONTEND_URL
                }
                return realGet(prop)
            })
            vi.spyOn(system, 'getOrThrow').mockImplementation((prop) => prop === AppSystemProp.FRONTEND_URL ? HTTP_FRONTEND_URL : realGetOrThrow(prop))
        })

        it('keeps the forwarded https scheme, as it did before AP_MCP_URL existed', async () => {
            const metadata = await discovery({ 'x-forwarded-proto': 'https', 'x-forwarded-host': 'apps.customer.example.com' })

            expect(metadata.issuer).toBe('https://apps.customer.example.com')
            expect(metadata.token_endpoint).toBe('https://apps.customer.example.com/token')
        })
    })
})

import { createHash, randomBytes } from 'node:crypto'
import { apId } from '@activepieces/core-utils'
import { FastifyInstance } from 'fastify'
import { mcpOAuthCodeService } from '../../src/app/mcp/oauth/code/mcp-oauth-code.service'

function generatePkce(): PkcePair {
    const verifier = randomBytes(32).toString('base64url')
    return { verifier, challenge: createHash('sha256').update(verifier).digest('base64url') }
}

async function registerClient({ app, tokenEndpointAuthMethod, redirectUris = [MCP_OAUTH_REDIRECT_URI] }: RegisterClientParams): Promise<RegisteredClient> {
    const payload: Record<string, unknown> = { redirect_uris: redirectUris }
    if (tokenEndpointAuthMethod !== undefined) {
        payload.token_endpoint_auth_method = <REDACTED>
    }
    const res = await app.inject({ method: 'POST', url: '/register', payload })
    return res.json()
}

async function issueCode({ clientId, codeChallenge, redirectUri = MCP_OAUTH_REDIRECT_URI }: IssueCodeParams): Promise<string> {
    return mcpOAuthCodeService.create({
        clientId,
        userId: apId(),
        projectId: apId(),
        platformId: apId(),
        redirectUri,
        codeChallenge,
        codeChallengeMethod: 'S256',
        scopes: ['mcp'],
    })
}

function basicHeader({ clientId, clientSecret }: { clientId: string, clientSecret: <REDACTED> }): string {
    return 'Basic ' + Buffer.from(`${clientId}:${clientSecret}`).toString('base64')
}

export const mcpOAuthTestHelpers = {
    generatePkce,
    registerClient,
    issueCode,
    basicHeader,
}

export const MCP_OAUTH_REDIRECT_URI = 'https://example.com/oauth/callback'

export type RegisteredClient = {
    client_id: string
    client_secret?: string
    token_endpoint_auth_method: <REDACTED>
}

type PkcePair = {
    verifier: string
    challenge: string
}

type RegisterClientParams = {
    app: FastifyInstance
    tokenEndpointAuthMethod?: string
    redirectUris?: string[]
}

type IssueCodeParams = {
    clientId: string
    codeChallenge: string
    redirectUri?: string
}

import { FastifyInstance } from 'fastify'
import { beforeAll, describe, expect, it } from 'vitest'
import { MCP_OAUTH_REDIRECT_URI, mcpOAuthTestHelpers } from '../../../helpers/mcp-oauth'
import { createTestContext, TestContext } from '../../../helpers/test-context'
import { setupTestEnvironment } from '../../../helpers/test-setup'

let app: FastifyInstance
let ctx: TestContext

const CHATGPT_RELAY_STATE = 'openai_platform_oauth_relay__'

const STATE_LIMIT = 2048

async function authorize({ state }: { state: string }): ReturnType<FastifyInstance['inject']> {
    const client = await mcpOAuthTestHelpers.registerClient({ app, tokenEndpointAuthMethod: '<REDACTED>' })
    const { challenge } = mcpOAuthTestHelpers.generatePkce()

    return app.inject({
        method: 'GET',
        url: '/authorize?' + new URLSearchParams({
            client_id: client.client_id,
            redirect_uri: MCP_OAUTH_REDIRECT_URI,
            response_type: 'code',
            code_challenge: challenge,
            code_challenge_method: 'S256',
            scope: 'mcp',
            resource: 'https://cloud.activepieces.com/mcp/platform',
            state,
        }).toString(),
    })
}

function authRequestIdFrom(location: string): string {
    return new URL(location, MCP_OAUTH_REDIRECT_URI).searchParams.get('authRequestId') ?? ''
}

async function consentThenApprove({ state }: { state: string }): Promise<URL> {
    const consent = await authorize({ state })
    expect(consent.statusCode).toBe(302)

    const approved = await ctx.post('/v1/mcp-oauth/approve', {
        authRequestId: authRequestIdFrom(String(consent.headers.location)),
        projectId: ctx.project.id,
    })
    expect(approved.statusCode).toBe(200)

    return new URL(approved.json().redirectUrl)
}

describe('ChatGPT platform connector conformance', () => {
    beforeAll(async () => {
        app = await setupTestEnvironment({ fresh: true })
        ctx = await createTestContext(app)
    })

    it('returns the relay state to the connector unchanged after consent', async () => {
        expect(CHATGPT_RELAY_STATE.length).toBeGreaterThan(512)

        const redirect = await consentThenApprove({ state: CHATGPT_RELAY_STATE })
        expect(redirect.searchParams.get('state')).toBe(CHATGPT_RELAY_STATE)
        expect(redirect.searchParams.get('code')).toEqual(expect.any(String))
    })

    it('stores and returns a relay state at the length limit', async () => {
        const state = 'a'.repeat(STATE_LIMIT)

        const redirect = await consentThenApprove({ state })

        expect(redirect.searchParams.get('state')).toBe(state)
        expect(redirect.searchParams.get('code')).toEqual(expect.any(String))
    })

    it('refuses a relay state beyond the length limit without a 5xx', async () => {
        const consent = await authorize({ state: 'a'.repeat(STATE_LIMIT + 1) })

        expect(consent.statusCode).toBe(400)
    })
})

import { FastifyInstance } from 'fastify'
import { beforeAll, describe, expect, it } from 'vitest'
import { databaseConnection } from '../../../../src/app/database/database-connection'
import { mcpOAuthClientService } from '../../../../src/app/mcp/oauth/client/mcp-oauth-client.service'
import { MCP_OAUTH_REDIRECT_URI, mcpOAuthTestHelpers, RegisteredClient } from '../../../helpers/mcp-oauth'
import { setupTestEnvironment } from '../../../helpers/test-setup'

let app: FastifyInstance

async function registerClient(tokenEndpointAuthMethod?: string): Promise<RegisteredClient> {
    return mcpOAuthTestHelpers.registerClient({ app, tokenEndpointAuthMethod })
}

async function exchange({ client, headers, body }: {
    client: RegisteredClient
    headers?: Record<string, string>
    body?: Record<string, string>
}): Promise<ReturnType<FastifyInstance['inject']>> {
    const { verifier, challenge } = mcpOAuthTestHelpers.generatePkce()
    const code = await mcpOAuthTestHelpers.issueCode({ clientId: client.client_id, codeChallenge: challenge })
    return app.inject({
        method: 'POST',
        url: '/token',
        headers: { 'content-type': 'application/x-www-form-urlencoded', ...headers },
        payload: new URLSearchParams({
            grant_type: 'authorization_code',
            code,
            code_verifier: verifier,
            redirect_uri: MCP_OAUTH_REDIRECT_URI,
            ...body,
        }).toString(),
    })
}

describe('MCP OAuth client authentication', () => {
    beforeAll(async () => {
        app = await setupTestEnvironment({ fresh: true })
    })

    describe('dynamic client registration', () => {
        it('defaults an omitted token_endpoint_auth_method to client_secret_basic and issues a secret (RFC 7591 section 2)', async () => {
            const client = await registerClient()

            expect(client.token_endpoint_auth_method).toBe('client_secret_basic')
            expect(typeof client.client_secret).toBe('string')
        })

        it('issues no secret when the client explicitly registers as public', async () => {
            const client = await registerClient('none')

            expect(client.token_endpoint_auth_method).toBe('none')
            expect(client.client_secret).toBeUndefined()
        })

        it('issues a secret for an explicit client_secret_basic registration', async () => {
            const client = await registerClient('client_secret_basic')

            expect(client.token_endpoint_auth_method).toBe('client_secret_basic')
            expect(typeof client.client_secret).toBe('string')
        })

        it('rejects an auth method outside the supported set', async () => {
            const res = await app.inject({
                method: 'POST',
                url: '/register',
                payload: { redirect_uris: [MCP_OAUTH_REDIRECT_URI], token_endpoint_auth_method: '<REDACTED>' },
            })

            expect(res.statusCode).toBe(400)
        })

        it.each([
            ['client_name', { redirect_uris: [MCP_OAUTH_REDIRECT_URI], client_name: 'a\u0000b' }],
            ['a redirect_uri', { redirect_uris: ['https://example.com/cb\u0000x'] }],
            ['every redirect_uri', { redirect_uris: [MCP_OAUTH_REDIRECT_URI, 'https://example.com/cb\u0000x'] }],
        ])('refuses to persist a control character in %s', async (_name, payload) => {
            const res = await app.inject({ method: 'POST', url: '/register', payload })

            expect(res.statusCode).toBe(400)
            expect(res.body).not.toContain('22021')
            expect(res.body).not.toContain('invalid byte sequence')
        })

        it('keeps the issued client secret out of caches (RFC 7591 section 3.2.1)', async () => {
            const res = await app.inject({
                method: 'POST',
                url: '/register',
                payload: { redirect_uris: [MCP_OAUTH_REDIRECT_URI] },
            })

            expect(res.statusCode).toBe(201)
            expect(res.headers['cache-control']).toBe('no-store')
            expect(res.headers['pragma']).toBe('no-cache')
        })
    })

    describe('token endpoint', () => {
        it('accepts a confidential client secret from the Authorization header', async () => {
            const client = await registerClient('client_secret_basic')

            const res = await exchange({
                client,
                headers: { authorization: mcpOAuthTestHelpers.basicHeader({ clientId: client.client_id, clientSecret: <REDACTED> ?? '' }) },
            })

            expect(res.statusCode).toBe(200)
            expect(res.json().access_token).toBeDefined()
        })

        it('accepts a confidential client secret from the request body', async () => {
            const client = await registerClient('client_secret_post')

            const res = await exchange({
                client,
                body: { client_id: client.client_id, client_secret: <REDACTED> ?? '' },
            })

            expect(res.statusCode).toBe(200)
            expect(res.json().access_token).toBeDefined()
        })

        it('accepts a confidential client secret over either transport regardless of the registered method', async () => {
            const basicClient = await registerClient('client_secret_basic')
            const postClient = await registerClient('client_secret_post')

            const basicClientViaBody = await exchange({
                client: basicClient,
                body: { client_id: basicClient.client_id, client_secret: <REDACTED> ?? '' },
            })
            const postClientViaHeader = await exchange({
                client: postClient,
                headers: { authorization: mcpOAuthTestHelpers.basicHeader({ clientId: postClient.client_id, clientSecret: <REDACTED> ?? '' }) },
            })

            expect(basicClientViaBody.statusCode).toBe(200)
            expect(postClientViaHeader.statusCode).toBe(200)
        })

        it('exchanges an authorization code for a public client with no secret', async () => {
            const client = await registerClient('none')

            const res = await exchange({ client, body: { client_id: client.client_id } })

            expect(res.statusCode).toBe(200)
            expect(res.json().access_token).toBeDefined()
        })

        it('rejects a confidential client that presents no credentials', async () => {
            const client = await registerClient('client_secret_post')

            const res = await exchange({ client, body: { client_id: client.client_id } })

            expect(res.statusCode).toBe(400)
            expect(res.json().error).toBe('invalid_client')
        })

        it('rejects a wrong secret in the Authorization header', async () => {
            const client = await registerClient('client_secret_basic')

            const res = await exchange({ client, headers: { authorization: mcpOAuthTestHelpers.basicHeader({ clientId: client.client_id, clientSecret: '<REDACTED>' }) } })

            expect(res.statusCode).toBe(400)
            expect(res.json().error).toBe('invalid_client')
        })

        it('rejects a wrong secret in the request body', async () => {
            const client = await registerClient('client_secret_post')

            const res = await exchange({ client, body: { client_id: client.client_id, client_secret: '<REDACTED>' } })

            expect(res.statusCode).toBe(400)
            expect(res.json().error).toBe('invalid_client')
        })

        it('refuses a request that presents credentials over both transports (RFC 6749 section 2.3)', async () => {
            const client = await registerClient('client_secret_basic')

            const res = await exchange({
                client,
                headers: { authorization: mcpOAuthTestHelpers.basicHeader({ clientId: client.client_id, clientSecret: <REDACTED> ?? '' }) },
                body: { client_id: client.client_id, client_secret: <REDACTED> ?? '' },
            })

            expect(res.statusCode).toBe(400)
            expect(res.json().error).toBe('invalid_request')
        })

        it('refuses a body secret alongside a malformed Basic header rather than silently ignoring the header', async () => {
            const client = await registerClient('client_secret_post')

            const res = await exchange({
                client,
                headers: { authorization: 'Basic ' + Buffer.from('proxy-user-with-no-colon').toString('base64') },
                body: { client_id: client.client_id, client_secret: <REDACTED> ?? '' },
            })

            expect(res.statusCode).toBe(400)
            expect(res.json().error).toBe('invalid_request')
        })

        it('does not let an empty Basic username adopt the client_id from the body', async () => {
            const client = await registerClient('none')

            const res = await exchange({
                client,
                headers: { authorization: 'Basic ' + Buffer.from(':password').toString('base64') },
                body: { client_id: client.client_id },
            })

            expect(res.statusCode).toBe(400)
        })

        it('rejects a client_id in the Authorization header that disagrees with the body (RFC 6749 section 2.3.1)', async () => {
            const client = await registerClient('client_secret_post')
            const other = await registerClient('none')

            const res = await exchange({
                client,
                headers: { authorization: mcpOAuthTestHelpers.basicHeader({ clientId: other.client_id, clientSecret: '' }) },
                body: { client_id: client.client_id, client_secret: <REDACTED> ?? '' },
            })

            expect(res.statusCode).toBe(400)
            expect(res.json().error).toBe('invalid_request')
        })

        it.each([
            ['empty scheme payload', 'Basic'],
            ['scheme with trailing space', 'Basic '],
            ['non-base64 payload', 'Basic !!!not-base64!!!'],
            ['colon-only payload', 'Basic ' + Buffer.from(':').toString('base64')],
            ['lowercase scheme', 'basic ' + Buffer.from('a:b').toString('base64')],
            ['bearer scheme', 'Bearer ' + Buffer.from('a:b').toString('base64')],
            ['malformed percent escape', 'Basic ' + Buffer.from('a%zz:b').toString('base64')],
        ])('never returns 5xx for a malformed Authorization header (%s)', async (_name, authorization) => {
            const client = await registerClient('none')

            const res = await exchange({ client, headers: { authorization }, body: { client_id: client.client_id } })

            expect(res.statusCode).toBeLessThan(500)
        })

        it.each([
            ['raw NUL', '%00abc'],
            ['encoded NUL', '%2500abc'],
            ['over-long identifier', 'a'.repeat(300)],
        ])('never reaches the database with an unusable client_id (%s)', async (_name, clientId) => {
            const viaBody = await app.inject({
                method: 'POST',
                url: '/token',
                headers: { 'content-type': 'application/x-www-form-urlencoded' },
                payload: `grant_type=authorization_code&code=x&code_verifier=y&redirect_uri=${MCP_OAUTH_REDIRECT_URI}&client_id=${clientId}`,
            })
            const viaHeader = await app.inject({
                method: 'POST',
                url: '/revoke',
                headers: {
                    'content-type': 'application/x-www-form-urlencoded',
                    authorization: 'Basic ' + Buffer.from(`${clientId}:secret`).toString('base64'),
                },
                payload: new URLSearchParams({ token: '<REDACTED>' }).toString(),
            })
            const viaQuery = await app.inject({
                method: 'GET',
                url: `/authorize?client_id=${clientId}&redirect_uri=${encodeURIComponent(MCP_OAUTH_REDIRECT_URI)}&response_type=code&code_challenge=abc&code_challenge_method=S256`,
            })

            expect(viaBody.statusCode).toBe(400)
            expect(viaHeader.statusCode).toBe(400)
            expect(viaQuery.statusCode).toBe(400)
            expect(viaHeader.body).not.toContain('22021')
        })

        it('sets cache-prevention headers on a successful token response (RFC 6749 section 5.1)', async () => {
            const client = await registerClient('none')

            const res = await exchange({ client, body: { client_id: client.client_id } })

            expect(res.statusCode).toBe(200)
            expect(res.headers['cache-control']).toBe('no-store')
            expect(res.headers['pragma']).toBe('no-cache')
        })

        it('sets cache-prevention headers on an error token response (RFC 6749 section 5.2)', async () => {
            const res = await app.inject({
                method: 'POST',
                url: '/token',
                headers: { 'content-type': 'application/x-www-form-urlencoded' },
                payload: new URLSearchParams({ grant_type: 'authorization_code' }).toString(),
            })

            expect(res.statusCode).toBe(400)
            expect(res.headers['cache-control']).toBe('no-store')
            expect(res.headers['pragma']).toBe('no-cache')
        })
    })

    describe('clients registered before the auth-method fix', () => {
        async function registerLegacyClient(): Promise<RegisteredClient> {
            const client = await mcpOAuthClientService.register({
                redirectUris: [MCP_OAUTH_REDIRECT_URI],
                tokenEndpointAuthMethod: '<REDACTED>',
            })
            await databaseConnection().query(
                'UPDATE mcp_oauth_client SET "tokenEndpointAuthMethod" = \'none\' WHERE "clientId" = $1',
                [client.client_id],
            )
            return { client_id: client.client_id, client_secret: <REDACTED> token_endpoint_auth_method: '<REDACTED>' }
        }

        it('keeps working when it still sends the secret it was issued', async () => {
            const legacy = await registerLegacyClient()

            const res = await exchange({
                client: legacy,
                body: { client_id: legacy.client_id, client_secret: <REDACTED> ?? '' },
            })

            expect(res.statusCode).toBe(200)
        })

        it('keeps working when it stops sending a secret', async () => {
            const legacy = await registerLegacyClient()

            const res = await exchange({ client: legacy, body: { client_id: legacy.client_id } })

            expect(res.statusCode).toBe(200)
        })
    })

    describe('refresh grant', () => {
        async function issueRefreshToken({ client, headers, body }: {
            client: RegisteredClient
            headers?: Record<string, string>
            body?: Record<string, string>
        }): Promise<string> {
            const res = await exchange({ client, headers, body })
            expect(res.statusCode).toBe(200)
            return res.json().refresh_token
        }

        it('renews a confidential client over the Authorization header, the path a default registration takes', async () => {
            const client = await registerClient()
            const authorization = mcpOAuthTestHelpers.basicHeader({ clientId: client.client_id, clientSecret: <REDACTED> ?? '' })
            const refreshToken = <REDACTED> issueRefreshToken({ client, headers: { authorization } })

            const res = await app.inject({
                method: 'POST',
                url: '/token',
                headers: { 'content-type': 'application/x-www-form-urlencoded', authorization },
                payload: new URLSearchParams({ grant_type: 'refresh_token', refresh_token: <REDACTED> }).toString(),
            })

            expect(res.statusCode).toBe(200)
            expect(res.json().access_token).toBeDefined()
            expect(res.json().refresh_token).toBe(refreshToken)
        })

        it('renews a confidential client over the request body', async () => {
            const client = await registerClient('client_secret_post')
            const credentials = { client_id: client.client_id, client_secret: <REDACTED> ?? '' }
            const refreshToken = <REDACTED> issueRefreshToken({ client, body: credentials })

            const res = await app.inject({
                method: 'POST',
                url: '/token',
                headers: { 'content-type': 'application/x-www-form-urlencoded' },
                payload: new URLSearchParams({ grant_type: 'refresh_token', refresh_token: <REDACTED> ...credentials }).toString(),
            })

            expect(res.statusCode).toBe(200)
            expect(res.json().refresh_token).toBe(refreshToken)
        })

        it('keeps renewing indefinitely, so a session does not die when the access token expires', async () => {
            const client = await registerClient()
            const authorization = mcpOAuthTestHelpers.basicHeader({ clientId: client.client_id, clientSecret: <REDACTED> ?? '' })
            let refreshToken = <REDACTED> issueRefreshToken({ client, headers: { authorization } })

            for (let renewal = 0; renewal < 3; renewal++) {
                const res = await app.inject({
                    method: 'POST',
                    url: '/token',
                    headers: { 'content-type': 'application/x-www-form-urlencoded', authorization },
                    payload: new URLSearchParams({ grant_type: 'refresh_token', refresh_token: <REDACTED> }).toString(),
                })
                expect(res.statusCode, `renewal ${renewal}`).toBe(200)
                refreshToken = <REDACTED>
            }
        })

        it('refuses to renew a confidential client that presents no secret', async () => {
            const client = await registerClient()
            const authorization = mcpOAuthTestHelpers.basicHeader({ clientId: client.client_id, clientSecret: <REDACTED> ?? '' })
            const refreshToken = <REDACTED> issueRefreshToken({ client, headers: { authorization } })

            const res = await app.inject({
                method: 'POST',
                url: '/token',
                headers: { 'content-type': 'application/x-www-form-urlencoded' },
                payload: new URLSearchParams({ grant_type: 'refresh_token', refresh_token: <REDACTED> client_id: client.client_id }).toString(),
            })

            expect(res.statusCode).toBe(400)
            expect(res.json().error).toBe('invalid_client')
        })
    })

    describe('revocation endpoint', () => {
        it('accepts a confidential client authenticating with the Authorization header', async () => {
            const client = await registerClient('client_secret_basic')

            const res = await app.inject({
                method: 'POST',
                url: '/revoke',
                headers: { 'content-type': 'application/x-www-form-urlencoded', authorization: mcpOAuthTestHelpers.basicHeader({ clientId: client.client_id, clientSecret: <REDACTED> ?? '' }) },
                payload: new URLSearchParams({ token: '<REDACTED>' }).toString(),
            })

            expect(res.statusCode).toBe(200)
        })

        it('rejects a confidential client presenting a wrong secret', async () => {
            const client = await registerClient('client_secret_basic')

            const res = await app.inject({
                method: 'POST',
                url: '/revoke',
                headers: { 'content-type': 'application/x-www-form-urlencoded', authorization: mcpOAuthTestHelpers.basicHeader({ clientId: client.client_id, clientSecret: '<REDACTED>' }) },
                payload: new URLSearchParams({ token: '<REDACTED>' }).toString(),
            })

            expect(res.statusCode).toBe(400)
            expect(res.json().error).toBe('invalid_client')
        })

        it('lets a public client revoke by naming itself', async () => {
            const client = await registerClient('none')

            const res = await app.inject({
                method: 'POST',
                url: '/revoke',
                headers: { 'content-type': 'application/x-www-form-urlencoded' },
                payload: new URLSearchParams({ token: '<REDACTED>', client_id: client.client_id }).toString(),
            })

            expect(res.statusCode).toBe(200)
        })

        it('refuses to revoke for a caller that presents no client identity (RFC 7009 section 2.1)', async () => {
            const res = await app.inject({
                method: 'POST',
                url: '/revoke',
                headers: { 'content-type': 'application/x-www-form-urlencoded' },
                payload: new URLSearchParams({ token: '<REDACTED>' }).toString(),
            })

            expect(res.statusCode).toBe(400)
            expect(res.json().error).toBe('invalid_client')
        })

        it('does not revoke another client\'s refresh token', async () => {
            const owner = await registerClient('none')
            const attacker = await registerClient('none')
            const { verifier, challenge } = mcpOAuthTestHelpers.generatePkce()
            const code = await mcpOAuthTestHelpers.issueCode({ clientId: owner.client_id, codeChallenge: challenge })
            const issued = await app.inject({
                method: 'POST',
                url: '/token',
                headers: { 'content-type': 'application/x-www-form-urlencoded' },
                payload: new URLSearchParams({
                    grant_type: 'authorization_code',
                    code,
                    client_id: owner.client_id,
                    code_verifier: verifier,
                    redirect_uri: MCP_OAUTH_REDIRECT_URI,
                }).toString(),
            })
            const refreshToken = <REDACTED>

            const revoke = await app.inject({
                method: 'POST',
                url: '/revoke',
                headers: { 'content-type': 'application/x-www-form-urlencoded' },
                payload: new URLSearchParams({ token: <REDACTED> client_id: attacker.client_id }).toString(),
            })
            const refreshed = await app.inject({
                method: 'POST',
                url: '/token',
                headers: { 'content-type': 'application/x-www-form-urlencoded' },
                payload: new URLSearchParams({
                    grant_type: 'refresh_token',
                    client_id: owner.client_id,
                    refresh_token: <REDACTED>
                }).toString(),
            })

            expect(revoke.statusCode).toBe(200)
            expect(refreshed.statusCode).toBe(200)
        })

        it('rejects a confidential client naming itself in the body without a secret', async () => {
            const client = await registerClient('client_secret_basic')

            const res = await app.inject({
                method: 'POST',
                url: '/revoke',
                headers: { 'content-type': 'application/x-www-form-urlencoded' },
                payload: new URLSearchParams({ token: '<REDACTED>', client_id: client.client_id }).toString(),
            })

            expect(res.statusCode).toBe(400)
            expect(res.json().error).toBe('invalid_client')
        })
    })
})

import { FastifyInstance } from 'fastify'
import { beforeAll, describe, expect, it } from 'vitest'
import { databaseConnection } from '../../../../src/app/database/database-connection'
import { mcpOAuthClientService } from '../../../../src/app/mcp/oauth/client/mcp-oauth-client.service'
import { MCP_OAUTH_REDIRECT_URI, mcpOAuthTestHelpers } from '../../../helpers/mcp-oauth'
import { setupTestEnvironment } from '../../../helpers/test-setup'

let app: FastifyInstance

async function redeemCode({ clientId, headers, body }: {
    clientId: string
    headers?: Record<string, string>
    body?: Record<string, string>
}): Promise<{ statusCode: number, json: () => Record<string, string> }> {
    const { verifier, challenge } = mcpOAuthTestHelpers.generatePkce()
    const code = await mcpOAuthTestHelpers.issueCode({ clientId, codeChallenge: challenge })
    return app.inject({
        method: 'POST',
        url: '/token',
        headers: { 'content-type': 'application/x-www-form-urlencoded', ...headers },
        payload: new URLSearchParams({
            grant_type: 'authorization_code',
            code,
            code_verifier: verifier,
            redirect_uri: MCP_OAUTH_REDIRECT_URI,
            ...body,
        }).toString(),
    })
}

function renew({ refreshToken, headers, body }: {
    refreshToken: <REDACTED>
    headers?: Record<string, string>
    body?: Record<string, string>
}): ReturnType<FastifyInstance['inject']> {
    return app.inject({
        method: 'POST',
        url: '/token',
        headers: { 'content-type': 'application/x-www-form-urlencoded', ...headers },
        payload: new URLSearchParams({ grant_type: 'refresh_token', refresh_token: <REDACTED> ...body }).toString(),
    })
}

describe('MCP OAuth client profiles', () => {
    beforeAll(async () => {
        app = await setupTestEnvironment({ fresh: true })
    })

    it('a client that omits the auth method and uses the Authorization header connects and renews', async () => {
        const client = await mcpOAuthTestHelpers.registerClient({ app })
        expect(client.token_endpoint_auth_method).toBe('client_secret_basic')
        const authorization = mcpOAuthTestHelpers.basicHeader({ clientId: client.client_id, clientSecret: <REDACTED> ?? '' })

        const exchanged = await redeemCode({ clientId: client.client_id, headers: { authorization } })
        expect(exchanged.statusCode).toBe(200)

        const renewed = await renew({ refreshToken: <REDACTED> headers: { authorization } })
        expect(renewed.statusCode).toBe(200)
    })

    it('a client that registers public and sends no credentials connects and renews', async () => {
        const client = await mcpOAuthTestHelpers.registerClient({ app, tokenEndpointAuthMethod: '<REDACTED>' })
        expect(client.client_secret).toBeUndefined()

        const exchanged = await redeemCode({ clientId: client.client_id, body: { client_id: client.client_id } })
        expect(exchanged.statusCode).toBe(200)

        const renewed = await renew({ refreshToken: <REDACTED> body: { client_id: client.client_id } })
        expect(renewed.statusCode).toBe(200)
    })

    it('a client that puts its secret in the body connects and renews', async () => {
        const client = await mcpOAuthTestHelpers.registerClient({ app, tokenEndpointAuthMethod: '<REDACTED>' })
        const credentials = { client_id: client.client_id, client_secret: <REDACTED> ?? '' }

        const exchanged = await redeemCode({ clientId: client.client_id, body: credentials })
        expect(exchanged.statusCode).toBe(200)

        const renewed = await renew({ refreshToken: <REDACTED> body: credentials })
        expect(renewed.statusCode).toBe(200)
    })

    it('a client registered before the fix keeps working across the upgrade, including renewal', async () => {
        const legacy = await mcpOAuthClientService.register({
            redirectUris: [MCP_OAUTH_REDIRECT_URI],
            tokenEndpointAuthMethod: '<REDACTED>',
        })
        await databaseConnection().query(
            'UPDATE mcp_oauth_client SET "tokenEndpointAuthMethod" = \'none\' WHERE "clientId" = $1',
            [legacy.client_id],
        )

        const stillSendingItsSecret = <REDACTED> redeemCode({
            clientId: legacy.client_id,
            body: { client_id: legacy.client_id, client_secret: <REDACTED> ?? '' },
        })
        expect(stillSendingItsSecret.statusCode).toBe(200)

        const renewed = await renew({
            refreshToken: <REDACTED>
            body: { client_id: legacy.client_id, client_secret: <REDACTED> ?? '' },
        })
        expect(renewed.statusCode).toBe(200)

        const withoutItsSecret = <REDACTED> redeemCode({ clientId: legacy.client_id, body: { client_id: legacy.client_id } })
        expect(withoutItsSecret.statusCode).toBe(200)
    })

    it('renewal yields an access token the MCP endpoint accepts', async () => {
        const client = await mcpOAuthTestHelpers.registerClient({ app, tokenEndpointAuthMethod: '<REDACTED>' })
        const exchanged = await redeemCode({ clientId: client.client_id, body: { client_id: client.client_id } })

        const renewed = await renew({ refreshToken: <REDACTED> body: { client_id: client.client_id } })
        const secondAccessToken = <REDACTED>

        expect(renewed.statusCode).toBe(200)
        expect(secondAccessToken).toBeDefined()
        expect(renewed.json().expires_in).toBe(900)
        const used = await app.inject({
            method: 'POST',
            url: '/mcp',
            headers: { authorization: `Bearer ${secondAccessToken}`, 'content-type': 'application/json' },
            payload: {},
        })
        expect(used.json().message).not.toBe('Invalid or expired access token')
    })

    it('refuses a bearer token that is not one of ours', async () => {
        const res = await app.inject({
            method: 'POST',
            url: '/mcp',
            headers: { authorization: 'Bearer <REDACTED>', 'content-type': 'application/json' },
            payload: {},
        })

        expect(res.statusCode).toBe(401)
        expect(res.headers['www-authenticate']).toContain('error="invalid_token"')
    })
})

import { randomBytes } from 'node:crypto'
import { FastifyInstance } from 'fastify'
import { beforeAll, describe, expect, it } from 'vitest'
import { databaseConnection } from '../../../../src/app/database/database-connection'
import { MCP_OAUTH_REDIRECT_URI, mcpOAuthTestHelpers } from '../../../helpers/mcp-oauth'
import { setupTestEnvironment } from '../../../helpers/test-setup'

let app: FastifyInstance

const OTHER_REDIRECT_URI = 'https://example.com/other/callback'

async function registerPublicClient(redirectUris: string[] = [MCP_OAUTH_REDIRECT_URI]): Promise<string> {
    const client = await mcpOAuthTestHelpers.registerClient({ app, tokenEndpointAuthMethod: '<REDACTED>', redirectUris })
    return client.client_id
}

function redeem({ clientId, code, verifier, redirectUri = MCP_OAUTH_REDIRECT_URI }: {
    clientId: string
    code: string
    verifier: string
    redirectUri?: string
}): ReturnType<FastifyInstance['inject']> {
    return app.inject({
        method: 'POST',
        url: '/token',
        headers: { 'content-type': 'application/x-www-form-urlencoded' },
        payload: new URLSearchParams({
            grant_type: 'authorization_code',
            code,
            client_id: clientId,
            code_verifier: verifier,
            redirect_uri: redirectUri,
        }).toString(),
    })
}

describe('MCP OAuth authorization code redemption', () => {
    beforeAll(async () => {
        app = await setupTestEnvironment({ fresh: true })
    })

    it('redeems a code exactly once', async () => {
        const clientId = await registerPublicClient()
        const { verifier, challenge } = mcpOAuthTestHelpers.generatePkce()
        const code = await mcpOAuthTestHelpers.issueCode({ clientId, codeChallenge: challenge })

        const first = await redeem({ clientId, code, verifier })
        const second = await redeem({ clientId, code, verifier })

        expect(first.statusCode).toBe(200)
        expect(second.statusCode).toBe(400)
        expect(second.json().error).toBe('invalid_grant')
    })

    it('redeems a code exactly once under concurrent redemption', async () => {
        const clientId = await registerPublicClient()
        const { verifier, challenge } = mcpOAuthTestHelpers.generatePkce()
        const code = await mcpOAuthTestHelpers.issueCode({ clientId, codeChallenge: challenge })

        const results = await Promise.all(
            Array.from({ length: 4 }, () => redeem({ clientId, code, verifier })),
        )

        expect(results.filter((res) => res.statusCode === 200)).toHaveLength(1)
    })

    it('refuses a code presented by a different client', async () => {
        const owner = await registerPublicClient()
        const attacker = await registerPublicClient()
        const { verifier, challenge } = mcpOAuthTestHelpers.generatePkce()
        const code = await mcpOAuthTestHelpers.issueCode({ clientId: owner, codeChallenge: challenge })

        const res = await redeem({ clientId: attacker, code, verifier })

        expect(res.statusCode).toBe(400)
        expect(res.json().error).toBe('invalid_grant')
    })

    it('refuses a code presented with a different redirect_uri', async () => {
        const clientId = await registerPublicClient([MCP_OAUTH_REDIRECT_URI, OTHER_REDIRECT_URI])
        const { verifier, challenge } = mcpOAuthTestHelpers.generatePkce()
        const code = await mcpOAuthTestHelpers.issueCode({ clientId, codeChallenge: challenge })

        const res = await redeem({ clientId, code, verifier, redirectUri: OTHER_REDIRECT_URI })

        expect(res.statusCode).toBe(400)
        expect(res.json().error).toBe('invalid_grant')
    })

    it('refuses an expired code', async () => {
        const clientId = await registerPublicClient()
        const { verifier, challenge } = mcpOAuthTestHelpers.generatePkce()
        const code = await mcpOAuthTestHelpers.issueCode({ clientId, codeChallenge: challenge })
        await databaseConnection().query(
            'UPDATE mcp_oauth_authorization_code SET "expiresAt" = NOW() - INTERVAL \'1 hour\' WHERE "code" = $1',
            [code],
        )

        const res = await redeem({ clientId, code, verifier })

        expect(res.statusCode).toBe(400)
        expect(res.json().error).toBe('invalid_grant')
    })

    it('refuses a code presented with the wrong PKCE verifier', async () => {
        const clientId = await registerPublicClient()
        const { challenge } = mcpOAuthTestHelpers.generatePkce()
        const code = await mcpOAuthTestHelpers.issueCode({ clientId, codeChallenge: challenge })

        const res = await redeem({ clientId, code, verifier: randomBytes(32).toString('base64url') })

        expect(res.statusCode).toBe(400)
        expect(res.json().error).toBe('invalid_grant')
    })
})

import { createHash, randomBytes } from 'node:crypto'
import { FastifyInstance } from 'fastify'
import { beforeAll, describe, expect, it } from 'vitest'
import { setupTestEnvironment } from '../../../helpers/test-setup'

let app: FastifyInstance
let base: string

const REDIRECT_URI = 'https://token.botframework.com/.auth/web/redirect'

async function get(path: string): Promise<{ status: number, body: Record<string, unknown> }> {
    const res = await fetch(`${base}${path}`)
    return { status: res.status, body: await res.json() as Record<string, unknown> }
}

describe('Microsoft Copilot Studio DCR prerequisites', () => {
    beforeAll(async () => {
        app = await setupTestEnvironment({ fresh: true })
        await app.listen({ port: 0, host: '127.0.0.1' })
        const address = app.server.address()
        base = `http://127.0.0.1:${typeof address === 'object' && address !== null ? address.port : 0}`
    })

    it('exposes protected resource metadata identifying its authorization server (RFC 9728)', async () => {
        const { status, body } = await get('/.well-known/oauth-protected-resource/mcp')

        expect(status).toBe(200)
        expect(body.resource).toEqual(expect.stringContaining('/mcp'))
        expect(body.authorization_servers).toEqual(expect.arrayContaining([expect.any(String)]))
    })

    it('points an unauthenticated MCP caller at that metadata via WWW-Authenticate', async () => {
        const res = await fetch(`${base}/mcp`, { method: 'POST' })

        expect(res.status).toBe(401)
        expect(res.headers.get('www-authenticate')).toEqual(expect.stringContaining('resource_metadata='))
    })

    it('publishes authorization server metadata including a registration_endpoint (RFC 8414)', async () => {
        const { status, body } = await get('/.well-known/oauth-authorization-server')

        expect(status).toBe(200)
        expect(body.registration_endpoint).toEqual(expect.stringContaining('/register'))
        expect(body.token_endpoint).toEqual(expect.stringContaining('/token'))
        expect(body.authorization_endpoint).toEqual(expect.stringContaining('/authorize'))
    })

    it('advertises S256, which Copilot enables by default for DCR', async () => {
        const { body } = await get('/.well-known/oauth-authorization-server')

        expect(body.code_challenge_methods_supported).toEqual(['S256'])
    })

    it('issues a client secret during registration, which Copilot requires', async () => {
        const res = await fetch(`${base}/register`, {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ redirect_uris: [REDIRECT_URI], client_name: 'Copilot Studio' }),
        })
        const client = await res.json() as Record<string, string>

        expect(res.status).toBe(201)
        expect(client.client_secret).toEqual(expect.any(String))
        expect(client.token_endpoint_auth_method).toBe('client_secret_basic')
    })

    it('completes the authorize step Copilot performs, redirecting to consent', async () => {
        const registered = await fetch(`${base}/register`, {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ redirect_uris: [REDIRECT_URI] }),
        })
        const client = await registered.json() as Record<string, string>
        const verifier = randomBytes(32).toString('base64url')
        const challenge = createHash('sha256').update(verifier).digest('base64url')

        const params = new URLSearchParams({
            client_id: client.client_id,
            redirect_uri: REDIRECT_URI,
            response_type: 'code',
            code_challenge: challenge,
            code_challenge_method: 'S256',
            scope: 'mcp',
            state: 'copilot-state',
        })
        const res = await fetch(`${base}/authorize?${params.toString()}`, { redirect: 'manual' })

        expect(res.status).toBe(302)
        expect(res.headers.get('location')).toEqual(expect.stringContaining('/mcp-authorize?authRequestId='))
    })

    it('accepts the issued secret over the Authorization header at the token endpoint', async () => {
        const registered = await fetch(`${base}/register`, {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ redirect_uris: [REDIRECT_URI] }),
        })
        const client = await registered.json() as Record<string, string>
        const authorization = 'Basic ' + Buffer.from(`${client.client_id}:${client.client_secret}`).toString('base64')

        const res = await fetch(`${base}/token`, {
            method: 'POST',
            headers: { 'content-type': 'application/x-www-form-urlencoded', authorization },
            body: new URLSearchParams({
                grant_type: 'authorization_code',
                code: 'a-code-that-was-never-issued',
                code_verifier: randomBytes(32).toString('base64url'),
                redirect_uri: REDIRECT_URI,
            }).toString(),
        })
        const body = await res.json() as Record<string, string>

        expect(res.status).toBe(400)
        expect(body.error).toBe('invalid_grant')
        expect(res.headers.get('cache-control')).toBe('no-store')
    })

    it('rejects the issued secret when it is wrong, over the same header', async () => {
        const registered = await fetch(`${base}/register`, {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ redirect_uris: [REDIRECT_URI] }),
        })
        const client = await registered.json() as Record<string, string>
