        it('stores the issued code as six digits', async () => {
            const statusCode = await requestCode(EMAIL)

            expect(statusCode).toBe(StatusCodes.NO_CONTENT)
            expect((await storedOtp(EMAIL))?.value).toMatch(/^[0-9]{6}$/)
