import { scimUserService } from './scim-user-service'

export const scimUserController: FastifyPluginAsyncZod = async (app) => {
    app.get('/', ListUsersRequest, async (request, reply) => {
        const platformId = request.principal.platform.id
        const result = await scimUserService(request.log).list({
            platformId,
            filter: request.query.filter,
            startIndex: request.query.startIndex,
            count: request.query.count,
        })
        return reply.status(StatusCodes.OK).send(result)
    })

    app.get('/:id', GetUserRequest, async (request, reply) => {
        const platformId = request.principal.platform.id
        const result = await scimUserService(request.log).getById({
            platformId,
            userId: request.params.id,
        })
        return reply.status(StatusCodes.OK).send(result)
    })

    app.post('/', CreateUserRequest, async (request, reply) => {
        const platformId = request.principal.platform.id
        const result = await scimUserService(request.log).create({
            platformId,
            request: request.body,
        })
        return reply.status(StatusCodes.CREATED).send(result)
    })

    app.put('/:id', ReplaceUserRequest, async (request, reply) => {
        const platformId = request.principal.platform.id
        const result = await scimUserService(request.log).replace({
            platformId,
            userId: request.params.id,
            request: request.body,
        })
        return reply.status(StatusCodes.OK).send(result)
    })

    app.patch('/:id', PatchUserRequest, async (request, reply) => {
        const platformId = request.principal.platform.id
        const result = await scimUserService(request.log).patch({
            platformId,
            userId: request.params.id,
            request: request.body,
        })
        return reply.status(StatusCodes.OK).send(result)
    })

    app.delete('/:id', DeleteUserRequest, async (request, reply) => {
        const platformId = request.principal.platform.id
        await scimUserService(request.log).deactivate({
            platformId,
            userId: request.params.id,
        })
        return reply.status(StatusCodes.NO_CONTENT).send()
    })
}

const scimSecurity = securityAccess.platformAdminOnly([PrincipalType.SERVICE])

const ListUsersRequest = {
    config: {
        security: scimSecurity,
    },
    schema: {
        querystring: ScimListQueryParams,
    },
}

const GetUserRequest = {
    config: {
        security: scimSecurity,
    },
    schema: {
        params: ScimResourceId,
    },
}

const CreateUserRequest = {
    config: {
        security: scimSecurity,
    },
    schema: {
        body: CreateScimUserRequest,
    },
}

const ReplaceUserRequest = {
    config: {
        security: scimSecurity,
    },
    schema: {
        params: ScimResourceId,
        body: ReplaceScimUserRequest,
    },
}

const PatchUserRequest = {
    config: {
        security: scimSecurity,
    },
    schema: {
        params: ScimResourceId,
        body: ScimPatchRequest,
    },
}

const DeleteUserRequest = {
    config: {
        security: scimSecurity,
    },
    schema: {
        params: ScimResourceId,
    },
}

export function toImageReplacements(images: unknown): ImageReplacement[] {
  if (Array.isArray(images)) {
    return images.flatMap((row) => {
      if (typeof row !== 'object' || row === null) {
        return [];
      }
      if (isEditorRow(row)) {
        return hasBothColumns(row) ? [{ imageObjectId: String(row.imageObjectId), url: String(row.url) }] : [];
      }
      return fromDictionary(row);
    });
  }
  if (typeof images === 'object' && images !== null) {
    return fromDictionary(images);
  }
  return [];
}

function isEditorRow(row: object): boolean {
  return EDITOR_COLUMNS.some((column) => column in row);
}

function hasBothColumns(row: object): row is Record<EditorColumn, unknown> {
  return EDITOR_COLUMNS.every((column) => column in row);
}

function fromDictionary(dictionary: object): ImageReplacement[] {
  return Object.entries(dictionary).map(([imageObjectId, url]) => ({ imageObjectId, url: String(url) }));
}

const EDITOR_COLUMNS = ['imageObjectId', 'url'] as const;

type EditorColumn = (typeof EDITOR_COLUMNS)[number];

export type ImageReplacement = {
  imageObjectId: string;
  url: string;
};
